You break when you don?t get a number, as shown in Example 4-2.
Example 4-2. Getting a number in a loop
#include <expected>
#include <iostream>
#include <string>
std::expected<double, std::string> get_number(std::istream & input_stream)
{
double number{};
input_stream >> number;
if(input_stream)
{
return number;
}
